import MtButton from "@/components/MtButton.vue";
export default {
  components: {
    MtButton
  },
  props: {
    height: {
      type: Number,
      required: true
    },
    label: {
      type: String,
      required: true
    },
    disabled: {
      type: Boolean,
      default: false
    },
    readonly: {
      type: Boolean,
      default: false
    },
    autofocus: {
      type: Boolean,
      default: false
    },
    value: {
      type: String,
      required: true
    },
    type: {
      type: String,
      required: true
    },
    // {"text", "password", "email"}
    rules: {
      type: Array,
      default: () => []
    },
    prependIcon: {
      type: String,
      required: true
    },
    appendIcon: {
      type: String,
      required: true
    }
  },
  computed: {
    bindValue: {
      get: function () {
        return this.value;
      },
      set: function (value) {
        this.$emit("change", value);
      }
    }
  }
};
